INSERT INTO public.faqs (topic, question, answer, sort_order, public_visible) VALUES
('PRODUCTS', 'Do you sell used phones?', 'Yes. We keep second-hand and refurbished handsets in store, checked before they go on the shelf and sold with a receipt. Stock changes often, so message us or call in to see what we have today.', 40, true),
('PRODUCTS', 'Do you stock accessories?', 'We carry cases, screen protectors, chargers, cables and earbuds for the popular models. If we have not got what you need on the shelf, ask and we will tell you whether we can order it in.', 50, true),
('VISITING', 'Where is the shop?', 'We are at 4 Aughton St, Ormskirk, L39 3BW, a couple of minutes from the town centre. Use the Get Directions button on the site and it will take you straight to the door.', 60, true);